/* ISLAMAREN ABENTURA — HIRU KALIFALDIAK V14
   Based on teacher's PDF page 15, with teacher-corrected 632–661.
   UI text in Basque. Scores local; not represented as server validated. */
(()=>{
 'use strict';
 const TYPES={ur:{name:'Urteak',icon:'▦'},fam:{name:'Gobernari-familia',icon:'♟'},hir:{name:'Hiriburua',icon:'♜'},evt:{name:'Gertaerak',icon:'▤'}};

 const TYPE_ART={ur:'categoria-urteak.webp',fam:'categoria-familia.webp',hir:'categoria-hiriburua.webp',evt:'categoria-gertaerak.webp'};
 const CARD_ART={
  'ort-ur':'data-632-661.webp','ome-ur':'data-661-750.webp','abb-ur':'data-750-1055.webp',
  'ort-fam':'familia-ondorengoak.webp','ome-fam':'familia-omeiarrak.webp','abb-fam':'familia-abbastarrak.webp',
  'ort-hir':'hiriburua-medina.webp','ome-hir':'hiriburua-damasko.webp','abb-hir':'hiriburua-bagdad.webp',
  'ort-evt':'gertaera-ortodoxoa.webp','ome-evt':'gertaera-omeiatarrak.webp','abb-evt':'gertaera-abbastarrak.webp'
 };
 const COLUMNS=[
  {id:'ort',name:'Kalifaldi ortodoxoa',city:'Medina',art:'cal14-medina.webp',map:'cal14-medina-map.webp'},
  {id:'ome',name:'Omeiatar kalifaldia',city:'Damasko',art:'cal14-damasko.webp',map:'cal14-damasko-map.webp'},
  {id:'abb',name:'Abbastar kalifaldia',city:'Bagdad',art:'cal14-bagdad.webp',map:'cal14-bagdad-map.webp'}
 ];
 const CARDS=[
  {id:'ort-ur',type:'ur',text:'632–661'},
  {id:'ort-fam',type:'fam',text:'Mahomaren ondorengoak'},
  {id:'ort-hir',type:'hir',text:'Medina'},
  {id:'ort-evt',type:'evt',text:'Sirian, Palestinan, Egipton, Afrikako iparraldeko zati batean, Mesopotamian eta Persian zehar zabaldu.'},
  {id:'ome-ur',type:'ur',text:'661–750'},
  {id:'ome-fam',type:'fam',text:'Omeiarrak'},
  {id:'ome-hir',type:'hir',text:'Damasko'},
  {id:'ome-evt',type:'evt',text:'Hedapenik handiena lortu, mendebalderantz: Afrikako iparraldean eta Iberiar penintsulan zehar.'},
  {id:'abb-ur',type:'ur',text:'750–1055'},
  {id:'abb-fam',type:'fam',text:'Abbastarrak'},
  {id:'abb-hir',type:'hir',text:'Bagdad'},
  {id:'abb-evt',type:'evt',text:'Kreta eta Sizilia konkistatu ondoren, musulmanen zabalkundea gelditu. 1055ean, turkiarrek kaliferria konkistatu.'}
 ];
 const SCORE_KEY='islama-v4-puntuazioak';
 const esc=s=>String(s).replace(/[&<>"']/g,k=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[k]));
 const asset=n=>(window.ISLAMA_EMBED||{})[n]||'assets/'+n;
 let root=null,timer=null,st=null;
 const q=(s)=>root?.querySelector(s);
 const qAll=(s)=>[...(root?.querySelectorAll(s)||[])];
 const ids=['arabia','denbora','bost','hedapena','kalifaldi','gizartea','hiria','merkataritza','artea','ondarea'];
 function shuffle(arr){let a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
 function init(){
  if(root)return;
  root=document.createElement('div');root.id='cv14-root';root.style.setProperty('--cv14-back',`url("${asset('cal14-background.webp')}")`);
  root.style.setProperty('--cv14-side',`url("${asset('cal14-medina.webp')}")`);
  root.innerHTML=`<div class="cv14-game">
   <header class="cv14-hud"><button type="button" class="cv14-home" id="cv14-home" aria-label="Jokoen menura itzuli">⌂</button><div class="cv14-title">✦ &nbsp; 5. Hiru kalifaldiak &nbsp; ✦</div><span class="cv14-lives" id="cv14-lives">❤️❤️❤️</span><span class="cv14-hud-stat" id="cv14-score">Puntuak: 0</span><span class="cv14-hud-stat" id="cv14-time">◷ 03:00</span><button type="button" class="cv14-sound" id="cv14-sound" aria-label="Soinua piztu edo itzali" title="Soinua">♫</button></header>
   <div class="cv14-layout"><aside class="cv14-sidebar"><div class="cv14-medal">5. JOKOA</div><h2>Kalifaldien erronka</h2><div class="cv14-side-illustr" role="img" aria-label="Medinako arkitektura ilustratua">✦</div><p>Lotu informazio bakoitza dagokion kalifaldiarekin.</p><span class="cv14-progress" id="cv14-progress">0/12</span><div class="cv14-pips" id="cv14-pips"></div><div class="cv14-hint"><strong>💡 Aholkua:</strong><p>Irakurri hiriburua eta urteak ondo. Hautatu txartela eta egin klik dagokion hutsunean.</p></div></aside>
   <main class="cv14-center"><div class="cv14-banner">✦ &nbsp; Arrastatu datuak dagokion kalifaldira. &nbsp; ✦</div><div class="cv14-columns" id="cv14-columns"></div><div class="cv14-tray"><div class="cv14-tray-title"><span>✦ &nbsp; Nahasitako txartelak</span><div class="cv16-tray-tools"><button type="button" id="cv16-read" class="cv16-read" aria-label="Aukeratutako txartelaren azalpen osoa irakurri">Irakurri aukeratutakoa</button><span id="cv14-placed">Kokatuta: 0/12</span></div></div><div class="cv14-cards" id="cv14-cards"></div></div><div class="cv14-actions"><button type="button" id="cv14-clear" class="cv14-clear">↶ Berrantolatu</button><button type="button" id="cv14-verify" class="cv14-verify" disabled>✓ Egiaztatu</button></div><div id="cv14-feedback" class="cv14-feedback" role="status" aria-live="polite">Hautatu txartela eta egin klik dagokion lekuan.</div></main>
   <aside class="cv14-rank"><h2>🏆 TOP 10</h2><div id="cv14-rank-rows" class="cv14-rank-rows"></div><div id="cv14-rank-note" class="cv14-rank-empty">Oraindik ez dago puntuaziorik.</div><div class="cv14-note">Ordenagailu honetako sailkapena</div></aside></div>
   <nav class="cv14-bottomnav" aria-label="Jokoen nabigazioa"><button type="button" class="cv14-nav-btn" id="cv14-previous">← Aurrekoa</button><div class="cv14-numbers" id="cv14-nav-numbers"></div><button type="button" class="cv14-nav-btn" id="cv14-next">Hurrengoa →</button></nav>
   <div class="cv14-curtain" id="cv14-intro"><div class="cv14-modal"><div style="font-size:47px">🏛️ ✦ 🏛️</div><h2>5. Hiru kalifaldiak</h2><p>12 txartel, hiru kalifaldi eta 3 bizitza. Irakurri datuak eta kokatu dagokion tokian. Erantzunak hasieran nahasita daude; kokatu datuak hiru kalifaldietan.</p><p><strong>PROBA LOKALA:</strong> errekorrak ordenagailu honetan gordeko dira.</p><label for="cv14-nickname">Zure goitizena</label><input id="cv14-nickname" maxlength="18" placeholder="Adibidez: Historialaria7" autocomplete="off"><p class="cv14-error" id="cv14-nickerror"></p><div class="cv14-modal-actions"><button type="button" class="cv14-primary" id="cv14-start">▶ Jolastu</button><button type="button" class="cv14-secondary" id="cv14-cancel">← Menura itzuli</button></div></div></div>
   <div class="cv14-curtain cv14-hidden" id="cv14-result"><div class="cv14-modal"><div style="font-size:52px" id="cv14-result-emoji">🏆</div><h2 id="cv14-result-title">Zorionak!</h2><div class="cv14-modal-score" id="cv14-result-score">0 puntu</div><p id="cv14-result-detail"></p><p id="cv14-record"></p><div class="cv14-modal-actions"><button type="button" class="cv14-primary" id="cv14-replay">↻ Berriro jokatu</button><button type="button" class="cv14-secondary" id="cv14-done">⌂ Jokoen menura</button></div></div></div>
  </div>`;
  document.body.appendChild(root);
  q('#cv14-home').addEventListener('click',close);
  q('#cv14-cancel').addEventListener('click',close);
  q('#cv14-done').addEventListener('click',close);
  q('#cv14-previous').addEventListener('click',()=>navigate(4));
  q('#cv14-next').addEventListener('click',()=>navigate(6));
  q('#cv14-start').addEventListener('click',start);
  q('#cv14-replay').addEventListener('click',start);
  q('#cv14-nickname').addEventListener('keydown',e=>{if(e.key==='Enter')start()});
  q('#cv14-verify').addEventListener('click',verify);
  q('#cv14-clear').addEventListener('click',clearNonLocked);
  q('#cv16-read').addEventListener('click',showSelectedDetail);
  q('#cv14-sound').addEventListener('click',()=>{if(!st)return;st.sound=!st.sound;q('#cv14-sound').textContent=st.sound?'♫':'♪'});
  q('#cv14-nav-numbers').innerHTML=ids.map((id,i)=>`<button class="cv14-num ${i===4?'active':''}" type="button" data-jump="${i+1}" aria-label="${i+1}. jokoa">${i+1}</button>`).join('');
  qAll('[data-jump]').forEach(b=>b.addEventListener('click',()=>navigate(Number(b.dataset.jump))));
 }
 function launch(){init();clearInterval(timer);timer=null;st=null;const main=document.getElementById('home-screen');if(main)main.classList.add('hidden');const game=document.getElementById('game-screen');if(game)game.classList.add('hidden');root.classList.add('cv14-on');q('#cv14-result').classList.add('cv14-hidden');q('#cv14-intro').classList.remove('cv14-hidden');try{q('#cv14-nickname').value=localStorage.getItem('islama-v14-last-nickname')||''}catch{q('#cv14-nickname').value=''};q('#cv14-nickerror').textContent='';updateRank();root.scrollTop=0;setTimeout(()=>q('#cv14-nickname')?.focus(),70)}
 function close(){if(!root)return;clearInterval(timer);timer=null;root.classList.remove('cv14-on');document.getElementById('home-screen')?.classList.remove('hidden');document.getElementById('game-screen')?.classList.add('hidden');window.scrollTo({top:0,behavior:'instant'})}
 function navigate(n){if(n===5){launch();return}close();const btn=document.querySelector(`.game-tile[data-game="${ids[n-1]}"]`);if(btn)btn.click();}
 function start(){init();const name=q('#cv14-nickname').value.trim().normalize('NFC');if(!/^[\p{L}\p{N}_ -]{2,18}$/u.test(name)){q('#cv14-nickerror').textContent='Idatzi 2 eta 18 karaktere arteko goitizen bat.';q('#cv14-nickname').focus();return}try{localStorage.setItem('islama-v14-last-nickname',name)}catch{}
  clearInterval(timer);st={name,remaining:180,started:Date.now(),lives:3,mistakes:0,done:false,selected:null,positions:{},earned:new Set(),cardOrder:shuffle(CARDS.map(c=>c.id)),sound:false};q('#cv14-sound').textContent='♪';q('#cv14-intro').classList.add('cv14-hidden');q('#cv14-result').classList.add('cv14-hidden');q('#cv14-feedback').textContent='Hautatu txartela eta kokatu dagokion hutsunean.';q('#cv14-feedback').className='cv14-feedback';render();timer=setInterval(()=>{if(!st||st.done)return;st.remaining=Math.max(0,st.remaining-1);updateHud();if(st.remaining===0)finish(false,'Denbora amaitu da.')},1000);
 }
 function card(id){return CARDS.find(c=>c.id===id)}
 function score(){if(!st)return 0;return Math.max(0,Math.min(1000,70*st.earned.size+(st.earned.size===12?Math.round(160*st.remaining/180):0)-80*st.mistakes))}
 function rankRecords(){let rootData={};try{rootData=JSON.parse(localStorage.getItem(SCORE_KEY)||'{}')}catch{}return Object.values(rootData.kalifaldi||{}).filter(x=>typeof x.score==='number').sort((a,b)=>b.score-a.score||a.timestamp-b.timestamp).slice(0,10)}
 function updateRank(){const records=rankRecords();if(!q('#cv14-rank-rows'))return;q('#cv14-rank-rows').innerHTML=Array.from({length:10},(_,i)=>{let r=records[i];return `<div class="cv14-rank-row"><span>${i<3?['🥇','🥈','🥉'][i]:i+1+'.'}</span><span>${r?esc(r.name):'—'}</span><strong>${r?Number(r.score).toLocaleString('eu-ES'):'—'}</strong></div>`}).join('');q('#cv14-rank-note').style.display=records.length?'none':'block'}
 function saveRecord(){let data={};try{data=JSON.parse(localStorage.getItem(SCORE_KEY)||'{}')}catch{}if(!data.kalifaldi)data.kalifaldi={};const k=st.name.toLocaleLowerCase('eu-ES');const old=data.kalifaldi[k];const improved=!old||score()>old.score;if(improved)data.kalifaldi[k]={name:st.name,score:score(),timestamp:Date.now()};try{localStorage.setItem(SCORE_KEY,JSON.stringify(data));return improved}catch{return false}}
 function updateHud(){if(!st)return;q('#cv14-score').textContent='Puntuak: '+score().toLocaleString('eu-ES');q('#cv14-lives').textContent='❤️'.repeat(st.lives)+'🖤'.repeat(3-st.lives);q('#cv14-time').textContent='◷ '+String(Math.floor(st.remaining/60)).padStart(2,'0')+':'+String(st.remaining%60).padStart(2,'0');q('#cv14-progress').textContent=st.earned.size+'/12';q('#cv14-pips').innerHTML=Array.from({length:12},(_,i)=>`<i class="${i<st.earned.size?'earned':''}"></i>`).join('');q('#cv14-placed').textContent='Kokatuta: '+Object.keys(st.positions).length+'/12';q('#cv14-verify').disabled=st.done||st.lives<=0}
 function render(){if(!st)return;const cols=q('#cv14-columns');cols.innerHTML=COLUMNS.map(col=>`<section class="cv14-column" data-cal="${col.id}"><h3 class="cv14-col-head">${esc(col.name)}</h3><div class="cv14-rows">${Object.entries(TYPES).map(([t,desc])=>{const slot=col.id+'-'+t;const id=st.positions[slot];const item=id?card(id):null;const ok=st.earned.has(slot);return `<button type="button" class="cv14-drop ${ok?'cv14-ok':''}" data-slot="${slot}" data-type="${t}" title="${item?esc(item.text):esc(desc.name)}" ${ok?'disabled':''}><span class="cv14-drop-label"><img class="cv16-category-art" src="${asset(TYPE_ART[t])}" alt="" draggable="false">${esc(desc.name)}:</span><span class="cv14-drop-content">${item?`<img class="cv16-filled-art" src="${asset(CARD_ART[item.id])}" alt="" draggable="false"><span class="cv16-filled-text">${esc(item.text)}${ok?' ✓':''}</span>`:`<img class="cv16-ghost" src="${asset(TYPE_ART[t])}" alt="" draggable="false"><span class="cv16-empty-text">Jarri txartela</span>`}</span></button>`}).join('')}</div><div class="cv14-city" style="background-image:url('${asset(col.art)}')"><span class="cv14-city-name">${esc(col.city)}</span><img class="cv14-map" src="${asset(col.map)}" alt="${esc(col.name)}: PDFko mapa"></div></section>`).join('');
  q('#cv14-cards').innerHTML=st.cardOrder.map(id=>{const c=card(id);const placed=Object.values(st.positions).includes(id);return `<button type="button" class="cv14-card ${st.selected===id?'cv14-selected':''} ${placed?'cv14-placed':''}" data-card="${id}" data-type="${c.type}" title="${esc(c.text)}" aria-label="${esc(c.text)}" draggable="${!placed}" ${placed?'disabled':''}><img class="cv16-card-art" src="${asset(CARD_ART[c.id])}" alt="" draggable="false"><span class="cv16-card-label">${esc(c.text)}</span></button>`}).join('');
  qAll('[data-card]').forEach(b=>{b.addEventListener('click',()=>{if(st.done)return;st.selected=b.dataset.card;render();feedback('Aukeratuta: '+card(st.selected).text,'')});b.addEventListener('dragstart',e=>{if(st.done)return;e.dataTransfer.setData('text/plain',b.dataset.card);e.dataTransfer.effectAllowed='move';st.selected=b.dataset.card});});
  qAll('[data-slot]').forEach(b=>{b.addEventListener('click',()=>{if(st.done)return;if(st.selected)place(b.dataset.slot,st.selected);else if(st.positions[b.dataset.slot])remove(b.dataset.slot);else chooseForSlot(b.dataset.slot)});b.addEventListener('dragover',e=>{if(st.done)return;e.preventDefault();b.classList.add('cv14-hover')});b.addEventListener('dragleave',()=>b.classList.remove('cv14-hover'));b.addEventListener('drop',e=>{if(st.done)return;e.preventDefault();b.classList.remove('cv14-hover');place(b.dataset.slot,e.dataTransfer.getData('text/plain')||st.selected)})});
  updateHud();updateRank();
 }
 function chooseForSlot(slot){
   if(!st||st.done)return;
   const type=slot.split('-')[1];
   const available=CARDS.filter(c=>c.type===type&&!Object.values(st.positions).includes(c.id));
   const popup=document.createElement('div');
   popup.className='cv14-curtain';popup.id='cv14-picker';popup.setAttribute('role','dialog');popup.setAttribute('aria-modal','true');
   popup.innerHTML=`<div class="cv14-modal"><h2>Aukeratu txartela</h2><p>${esc(TYPES[type].name)} · dagokion kalifaldia</p><div class="cv14-choice-list">${available.map(c=>`<button type="button" data-choice="${c.id}" class="cv16-choice"><img src="${asset(CARD_ART[c.id])}" alt="" draggable="false">${esc(c.text)}</button>`).join('')}</div><div class="cv14-modal-actions"><button type="button" class="cv14-secondary" data-cancel="1">Utzi</button></div></div>`;
   root.querySelector('.cv14-game').appendChild(popup);
   popup.querySelectorAll('[data-choice]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.choice;popup.remove();place(slot,id)}));
   popup.querySelector('[data-cancel]').addEventListener('click',()=>popup.remove());
   popup.addEventListener('click',e=>{if(e.target===popup)popup.remove()});
 }

 function showSelectedDetail(){
  if(!st||st.done)return;
  if(!st.selected){feedback('Hautatu lehenengo txartel bat irakurtzeko.','info');return;}
  const c=card(st.selected);if(!c)return;
  q('#cv14-detail')?.remove();
  const popup=document.createElement('div');popup.id='cv14-detail';popup.className='cv14-curtain cv16-detail-curtain';popup.setAttribute('role','dialog');popup.setAttribute('aria-modal','true');popup.setAttribute('aria-label','Txartelaren azalpen osoa');
  popup.innerHTML=`<div class="cv14-modal cv16-detail-modal"><img src="${asset(CARD_ART[c.id])}" alt="" draggable="false"><div><h2>${esc(TYPES[c.type].name)}</h2><p>${esc(c.text)}</p><button type="button" class="cv14-secondary" id="cv16-close-detail">Itxi</button></div></div>`;
  root.querySelector('.cv14-game').appendChild(popup);
  popup.querySelector('#cv16-close-detail').addEventListener('click',()=>popup.remove());
  popup.addEventListener('click',e=>{if(e.target===popup)popup.remove()});
  popup.addEventListener('keydown',e=>{if(e.key==='Escape')popup.remove()});
  popup.querySelector('#cv16-close-detail').focus();
 }
 function feedback(msg,kind=''){const el=q('#cv14-feedback');el.textContent=msg;el.className='cv14-feedback'+(kind?' '+kind:'')}
 function place(slot,id){if(!st||st.done)return;const c=card(id);if(!c)return;if(st.earned.has(slot)){feedback('Hau dagoeneko ondo egiaztatuta dago.','bad');return}const slotType=slot.split('-')[1];if(c.type!==slotType){feedback('Txartel hau beste mota bateko hutsunean jarri behar da.','bad');return}
  let from=Object.keys(st.positions).find(key=>st.positions[key]===id);if(from===slot){st.selected=null;render();return}const displaced=st.positions[slot];if(from)delete st.positions[from];if(displaced&&from&&!st.earned.has(from))st.positions[from]=displaced;st.positions[slot]=id;st.selected=null;render();feedback('Txartela kokatuta. Jarraitu besteekin.','');}
 function remove(slot){if(!st||st.done||st.earned.has(slot))return;delete st.positions[slot];render();feedback('Txartela kendu duzu.','');}
 function clearNonLocked(){if(!st||st.done)return;for(const slot of Object.keys(st.positions))if(!st.earned.has(slot))delete st.positions[slot];st.selected=null;render();feedback('Egiaztatu gabe zeuden txartelak itzuli dira.','')}
 function verify(){if(!st||st.done||st.lives<=0)return;const slots=Object.keys(st.positions);if(slots.length<12){feedback('Osatu 12 txartelak egiaztatu aurretik. Ez duzu bizitzarik galdu.','info');return}const wrong=[];const fresh=[];for(const c of CARDS){if(st.positions[c.id]===c.id){if(!st.earned.has(c.id)){st.earned.add(c.id);fresh.push(c.id)}}else if(!st.earned.has(c.id))wrong.push(c.id)}
  if(wrong.length){st.mistakes++;st.lives=Math.max(0,st.lives-1);const errSlots=new Set(wrong);for(const k of errSlots)delete st.positions[k];render();for(const k of errSlots)q(`[data-slot="${k}"]`)?.classList.add('cv14-bad');feedback(`${fresh.length} ondo; ${wrong.length} zuzendu beharrekoak. Bizitza bat galdu duzu.`,'bad');if(st.lives===0)finish(false,'Bizitzak amaitu dira.');}
  else{render();feedback('Bikain! Hiru kalifaldiak osatu dituzu!','good');const verifiedRound=st;setTimeout(()=>{if(st===verifiedRound)finish(true,'Hiru kalifaldiak ondo bereizi dituzu!')},700)}
 }
 function finish(won,reason){if(!st||st.done)return;st.done=true;clearInterval(timer);timer=null;const improved=won?saveRecord():false;updateHud();updateRank();q('#cv14-result-emoji').textContent=won?'🏆':'⌛';q('#cv14-result-title').textContent=won?'Zorionak!':'Partida amaitu da';q('#cv14-result-score').textContent=score().toLocaleString('eu-ES')+' puntu';q('#cv14-result-detail').textContent=reason+' · '+st.earned.size+'/12 ondo · '+st.mistakes+' huts · '+(180-st.remaining)+' segundo.';q('#cv14-record').textContent=won?(improved?'★ Errekor pertsonal berria!':'Zure errekorra mantendu duzu.'):'Partida osatu gabe: puntuazioa ez da errekorretan gordetzen.';q('#cv14-result').classList.remove('cv14-hidden')}
 window.CALIPHATES_V14={launch,close,inspect:()=>st?{positions:{...st.positions},earned:[...st.earned],score:score(),remaining:st.remaining,errors:st.mistakes,lives:st.lives}:null,place:(slot,id)=>place(slot,id),verify,finish};
})();

